import React, { useEffect, useRef, useState } from "react";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { IconButton } from "@mui/material";
import { useLocation, useNavigate } from "react-router-dom";
import OrderImage from "../../assets/orders/order1.png";
import ArrowDropDownIcon from "@mui/icons-material/ArrowDropDown";
import DownloadForOfflineIcon from "@mui/icons-material/DownloadForOffline";
import ConfirmedOrder from "../../assets/orders/confirmed_order.png";
import ProcessingOrder from "../../assets/orders/processing_order.png";
import ProductDispatched from "../../assets/orders/product_despatched.png";
import OnDelivery from "../../assets/orders/on_delivery.png";
import ProductDelivered from "../../assets/orders/product_delivered.png";
import http from "../../services/utility";
import { apisPath } from "../../utils/path";
import shippingAPI from "../../services/shippingService";
import { useDispatch } from "react-redux";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";
import CloseIcon from "@mui/icons-material/Close";

export default function OrderDetails() {
  const dispatch = useDispatch();
  const { state } = useLocation();
  const navigate = useNavigate();
  const [onStep, setOnStep] = useState(null);
  const stepContainer = useRef(null);
  const [stateData, setStateData] = useState(state?.data);
  const [trackingData, setTrackingData] = useState(null);
  const [trackingError, setTrackingError] = useState("");
  const [trackingLoading, setTrackingLoading] = useState(false);

  const [orderDetails, setOrderDetails] = useState({
    customerAddress: "",
    shippedToAddress: "",
    payment: {
      type: "",
      cardType: "",
      cardNumber: "",
      paymentEmail: "",
    },
    orderInformation: {
      orderTime: new Date(stateData?.createdAt).toLocaleString("en-US", {
        hour: "2-digit",
        minute: "2-digit",
        hour12: true,
      }),
      orderDate: new Date(stateData?.createdAt).toLocaleString("en-US", {
        weekday: "short",
        year: "numeric",
        month: "short",
        day: "numeric",
        timeZone: "UTC",
      }),
    },
  });
  const [tableHeader, setTableHeader] = useState([
    { name: "Order ID" },
    { name: "Customer Name" },
    { name: "Product" },
    { name: "Date" },
    { name: "Price" },
    { name: "Quantity" },
    // { name: "Status" },
  ]);

  const [tableData, setTableData] = useState(stateData?.product);

  const [trackingItemArray, setTrackingItemArray] = useState([
    { image: ConfirmedOrder, name: "Pending Pickup" },
    { image: ProcessingOrder, name: "In Transit" },
    {
      image: ProductDispatched,
      name: "Product dispatched",
    },
    {
      image: OnDelivery,
      name: "Out For Delivery",
    },
    {
      image: ProductDelivered,
      name: "Product delivered",
    },
  ]);

  useEffect(() => {
    if (stateData || trackingData) {
      const status = (
        trackingData?.status ||
        stateData?.status ||
        ""
      ).toUpperCase();

      if (
        status === "CANCELLED" ||
        status === "CANCELED" ||
        status === "REJECTED"
      ) {
        setOnStep(-1);
      } else if (status.startsWith("RT")) {
        setOnStep(-2); // RTO
      } else if (
        status === "PP" ||
        status === "BOOKED" ||
        status === "DATA RECEIVED"
      ) {
        setOnStep(0);
      } else if (status === "IT") {
        setOnStep(1);
      } else if (status === "EX") {
        setOnStep(2);
      } else if (status === "FD") {
        setOnStep(3);
      } else if (status === "DL") {
        setOnStep(4);
      } else {
        // Default based on original order status if no exact match
        if (stateData?.status === "Processing") setOnStep(0);
        else if (stateData?.status === "Accepted") setOnStep(1);
        else if (stateData?.status === "Shipped") setOnStep(2);
        else if (stateData?.status === "Out_for_Delivery") setOnStep(3);
        else if (stateData?.status === "Delivered") setOnStep(4);
        else if (
          stateData?.status === "Cancelled" ||
          stateData?.status === "Rejected"
        )
          setOnStep(-1);
        else if (stateData?.status?.toUpperCase().startsWith("RT"))
          setOnStep(-2);
        else setOnStep(0);
      }
    }
  }, [stateData, trackingData]);

  // useEffect(() => {
  //   if (stateData?.status?.toLowerCase() === "processing") {
  //     setOnStep(1);
  //   }
  // }, []);

  useEffect(() => {
    if (onStep !== null && stepContainer.current && onStep >= 0) {
      // calculating circle and line gap as well as line width for dynamic animation
      const hr_width = document
        .querySelector(".orders_detail__content__tracking__hr_line")
        .getBoundingClientRect().width;

      const transitionDuration = 0.4 * onStep;
      const _steps_width = parseInt(
        document
          .querySelector("div.orders_detail__content__tracking__steps")
          .getBoundingClientRect().width
      );

      const goTill =
        (_steps_width + hr_width) * parseInt(onStep) + _steps_width / 2;

      setTimeout(() => {
        stepContainer.current.style.transitionDuration = `${transitionDuration}s`;
        stepContainer.current.style.width = `${goTill + _steps_width / 2}px`;
      }, 1);
    }
  }, [onStep]);

  useEffect(() => {
    // console.log(state?.data);
    let orderData = {
      customerAddress:
        stateData?.address?.name +
        ", " +
        stateData?.address?.flat +
        ", " +
        stateData?.address?.landmark +
        ", " +
        stateData?.address?.city +
        ", " +
        stateData?.address?.state +
        ", " +
        stateData?.address?.pincode,
      shippedToAddress:
        stateData?.address?.name +
        ", " +
        stateData?.address?.flat +
        ", " +
        stateData?.address?.landmark +
        ", " +
        stateData?.address?.city +
        ", " +
        stateData?.address?.state +
        ", " +
        stateData?.address?.pincode,

      payment: {
        type: "cod",
        paymentEmail: stateData?.user?.email,
      },
    };
    setOrderDetails((prev) => {
      return {
        ...prev,
        customerAddress: orderData?.customerAddress,
        shippedToAddress: orderData?.shippedToAddress,
        payment: orderData?.payment,
      };
    });
  }, []);

  const loadTracking = async () => {
    const awb = stateData?.trackingID;
    if (!awb) {
      return;
    }
    setTrackingLoading(true);
    setTrackingError("");
    try {
      const response = await shippingAPI.trackShipment(awb);
      if (response?.data?.status) {
        setTrackingData(response.data.data);
      } else {
        setTrackingError(
          response?.data?.message || "Failed to fetch tracking information"
        );
      }
    } catch (error) {
      setTrackingError(
        error?.response?.data?.message || "Error fetching tracking information"
      );
    } finally {
      setTrackingLoading(false);
    }
  };

  useEffect(() => {
    loadTracking();
  }, []);

  const getStatusColor = (status) => {
    const statusColors = {
      Delivered: "text-green-600",
      "In Transit": "text-blue-600",
      "Out for Delivery": "text-orange-600",
      Pending: "text-yellow-600",
      Cancelled: "text-red-600",
      Returned: "text-red-600",
    };
    return statusColors[status] || "text-gray-600";
  };

  const formatDate = (dateString) => {
    if (!dateString) return "N/A";
    return new Date(dateString).toLocaleString();
  };

  const statusLabel = trackingData?.status
    ? trackingData.status.charAt(0).toUpperCase() +
    trackingData.status.slice(1)
    : "Unknown";

  const acceptOrder = async () => {
    await http
      .put(`${apisPath?.admin?.orderAccept}/${stateData?.id}`)
      .then((res) => {
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };
  const rejectOrder = async () => {
    try {
      const orderRes = await http.delete(
        `${apisPath?.admin?.orderReject}/${stateData?.id}`
      );

      let message =
        orderRes?.data?.message || "Order rejected successfully";

      try {
        const awb = stateData?.trackingID || stateData?.id;
        const shipRes = await shippingAPI.cancelShipment(awb);

        if (shipRes?.data?.status) {
          message = `${message} & shipment cancelled`;
        } else {
          dispatch(
            openTicker({
              title: "Error",
              body:
                shipRes?.data?.message || "Failed to cancel shipment",
            })
          );
        }
      } catch (err2) {
        dispatch(
          openTicker({
            title: "Error",
            body:
              err2?.response?.data?.message ||
              "Failed to cancel shipment",
          })
        );
      }

      dispatch(
        openSuccessTicker({
          title: "Success",
          body: message,
        })
      );
    } catch (err) {
      dispatch(
        openTicker({
          title: "Error",
          body: err?.response?.data?.message || "Failed to reject order",
        })
      );
    }
  };

  const getOrderInvoice = async () => {
    await http
      .get(`${apisPath?.admin?.orderInvoice}?awb=${stateData?.id}`)
      .then((res) => {
        document
          .getElementById("new_page_open")
          .setAttribute("href", res?.data)
          .click();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  return (
    <div className="orders_detail">
      <a
        href=""
        id="new_page_open"
        target="_blank"
        style={{ display: "none" }}
      ></a>
      <div className="detail__header">
        <IconButton
          aria-label="Back"
          className="back__button"
          onClick={() => navigate(-1)}
        >
          <ArrowBackIcon />
        </IconButton>
        <h3 className="page_heading">Order details</h3>
      </div>
      <div className="orders_detail__content">
        <div className="orders_detail__content__cards">
          <div className="orders_detail__content__cards__customer">
            <h4>Customer:</h4>
            <p>{orderDetails?.customerAddress}</p>
          </div>
          <div className="orders_detail__content__cards__customer">
            <h4>Shipped to:</h4>
            <p>{orderDetails?.shippedToAddress}</p>
          </div>
          <div className="orders_detail__content__cards__customer">
            <h4>Payment method:</h4>
            <p>
              {orderDetails?.payment?.type === "card"
                ? `${orderDetails?.payment?.cardType} ending ${orderDetails?.payment?.cardNumber}`
                : "Cash On Delivery"}
            </p>
            {/* <p>{orderDetails?.payment?.paymentEmail}</p> */}
          </div>
          <div className="orders_detail__content__cards__customer">
            <h4>Order date:</h4>
            <p>{orderDetails?.orderInformation?.orderTime}</p>
            <p>{orderDetails?.orderInformation?.orderDate}</p>
          </div>
        </div>

        <div className="orders_detail__content__product_summary">
          <h3>Product summary</h3>
          <div className="orders_detail__content__product_summary__table">
            <table className="orders__content__filter_content__table">
              <tr>
                {tableHeader?.map((header, index) => {
                  return (
                    <th key={index}>
                      <span>
                        {header?.name} <ArrowDropDownIcon />
                      </span>
                    </th>
                  );
                })}
              </tr>
              {tableData?.map((data, index) => {
                return (
                  <tr key={index}>
                    <td>{stateData?.orderID}</td>
                    <td>
                      {!stateData?.user?.name || stateData?.user?.name === ""
                        ? "Unknown"
                        : stateData?.user?.name}
                    </td>
                    <td>
                      <div className="product">
                        <img src={data?.images[0]} alt="Product Image" />
                        <div className="product__info">
                          <span>{data?.name}</span>
                          <span>Details: {data?.details[0]?.body}</span>
                        </div>
                      </div>
                    </td>
                    <td>
                      {new Date(data?.createdAt)?.toLocaleString("en-US", {
                        weekday: "short",
                        year: "numeric",
                        month: "short",
                        day: "numeric",
                        timeZone: "UTC",
                      })}
                    </td>
                    <td>&#8377; {data?.amount}</td>
                    <td>{data?.qty}</td>
                    {/* <td>
                      <div>
                        {stateData?.status === "PP" && "Pending Pickup"}
                        {stateData?.status === "IT" && "In Transit"}
                        {stateData?.status === "EX" && "Exception"}
                        {stateData?.status === "FD" && "Out For Delivery"}
                        {stateData?.status === "DL" && "Delivered"}
                        {stateData?.status === "RT" && "RTO"}
                        {stateData?.status === "RT-IT" && "RTO In Transit"}
                        {stateData?.status === "RT-DL" && "RTO Delivered"}
                      </div>
                    </td> */}
                  </tr>
                );
              })}
            </table>

            <hr />

            <div className="orders_detail__content__product_summary__table__total_tax">
              <div className="orders_detail__content__product_summary__table__total_tax__btns">
                {stateData?.status === "Processing" ? (
                  <>
                    <button
                      className="button-red button-green"
                      onClick={acceptOrder}
                    >
                      Accept
                    </button>
                    <button className="button-red" onClick={rejectOrder}>
                      Reject
                    </button>
                  </>
                ) : (
                  <button className="button-red" onClick={getOrderInvoice}>
                    <DownloadForOfflineIcon /> Download detail pdf
                  </button>
                )}
              </div>
              <div className="orders_detail__content__product_summary__table__total_tax__total_calculation">
                <div>
                  <span>Taxes</span>
                  <span>{stateData?.tax ? stateData?.tax : 0}</span>
                </div>
                <div>
                  <span>Total:</span>
                  <span>&#8377; {stateData?.amount}</span>
                </div>
                <div>
                  <span>Payment status:</span>
                  <span>
                    {stateData?.paymentMethod === "COD"
                      ? stateData?.paymentMethod
                      : "Payment Confirmed"}
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="orders_detail__content__product_summary orders_detail__content__tracking_order_no" style={{ display: 'flex', justifyContent: 'center', border: 'none', background: 'transparent' }}>
          <p style={{ fontSize: '1.2rem', fontWeight: '500' }}>
            Tracking order no - <span>{trackingData?.awb_number || stateData?.trackingID}</span>
          </p>
        </div>

        <div className="orders_detail__content__tracking">
          <div className="orders_detail__content__tracking__container">
            {onStep === -1 || onStep === -2 ? (
              <div className="orders_detail__content__status_display">
                <div
                  className={`orders_detail__content__status_display__icon_wrapper ${onStep === -2 ? "rto" : "cancelled"
                    }`}
                >
                  {onStep === -2 ? (
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      width="24"
                      height="24"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="#f97316"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M16 15v-1a4 4 0 00-4-4H8m0 0l3 3m-3-3l3-3"
                      />
                    </svg>
                  ) : (
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      width="24"
                      height="24"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="#ef4444"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M6 18L18 6M6 6l12 12"
                      />
                    </svg>
                  )}
                </div>
                <p
                  className={`orders_detail__content__status_display__text ${onStep === -2 ? "rto" : "cancelled"
                    }`}
                >
                  {onStep === -2
                    ? `RTO Status: ${trackingData?.status || stateData?.status}`
                    : "Order Cancelled"}
                </p>
                {onStep === -2 && trackingData?.history?.[0] && (
                  <p className="orders_detail__content__status_display__history">
                    {trackingData.history[0].message} -{" "}
                    {trackingData.history[0].location}
                  </p>
                )}
              </div>
            ) : (
              <>
                <div className="orders_detail__content__tracking__steps_container">
                  {trackingItemArray.map((item, index) => {
                    return (
                      <React.Fragment key={index}>
                        <Step
                          name={item?.name}
                          image={item?.image}
                          shaded={onStep !== null && index <= onStep}
                          render={true}
                        />
                        {index !== trackingItemArray.length - 1 && (
                          <div
                            className={`orders_detail__content__tracking__hr_line`}
                          ></div>
                        )}
                      </React.Fragment>
                    );
                  })}
                </div>
                <div
                  className="orders_detail__content__tracking__steps_container_front"
                  ref={stepContainer}
                >
                  <div className="orders_detail__content__tracking__steps_container orders_detail__content__tracking__steps_container_front_inner ">
                    {trackingItemArray.map((item, index) => {
                      return (
                        <React.Fragment key={index}>
                          <Step
                            name={item?.name}
                            image={item?.image}
                            render={false}
                          />
                          {index !== trackingItemArray.length - 1 && (
                            <div
                              className={`orders_detail__content__tracking__hr_line`}
                            ></div>
                          )}
                        </React.Fragment>
                      );
                    })}
                  </div>
                </div>
              </>
            )}
          </div>
        </div>

        {trackingLoading && (
          <div className="loading" style={{ textAlign: 'center', marginTop: '20px' }}>Loading tracking details...</div>
        )}
        {trackingError && (
          <div className="error-message" style={{ textAlign: 'center', color: 'red', marginTop: '20px' }}>{trackingError}</div>
        )}
      </div>
    </div>
  );
}

const Step = (props) => {
  return (
    <div className={"orders_detail__content__tracking__steps"}>
      <img src={props?.image} alt={props?.name} />
      {props?.render && (
        <h3 className={`${!props?.shaded ? "color-black" : ""}`}>
          {props.name}
        </h3>
      )}
    </div>
  );
};
